/** Package.json contributions, generated by scripts/gen-contributions.mjs. */

export interface CommandDef {
  command: string;
  title: string;
  category?: string;
  icon?: string;
  enablement?: string;
}

export interface MenuItem {
  command: string;
  when?: string;
  group?: string;
  alt?: string;
}

export interface KeybindingDef {
  command: string;
  key: string;
  mac?: string;
  when?: string;
}

export interface ConfigProperty {
  type: 'string' | 'boolean' | 'number' | 'array' | 'object';
  default: unknown;
  description?: string;
  markdownDescription?: string;
  scope?: 'application' | 'machine' | 'window' | 'resource' | 'machine-overridable';
  enum?: string[];
  items?: { type: string; enum?: string[] };
  minimum?: number;
  order?: number;
}

export const CATEGORY = 'Folium';

/**
 * Menus show the command title, the Command Palette shows "Folium: <title>" because every command is
 * contributed with `category: CATEGORY` (see MANIFEST below and scripts/gen-contributions.mjs).
 */
const commandTitle = (title: string): string => title;

